-- 受注 00001 | [2] 見積00002の第1回受注 (売上計上前)
INSERT INTO SALES_ORDER (
    SALES_ORDER_ID, SALES_ORDER_NO, BUSINESS_DATE, PARTNER_ID, PARTNER_NAME, WAREHOUSE_ID, WAREHOUSE_NAME,
    ASSIGNEE_ID, ASSIGNEE_NAME, DUE_DATE, NOTE, PROGRESS_STATUS
)
SELECT SEQ_SALES_ORDER.NEXTVAL, LPAD(TO_CHAR(SEQ_SALES_ORDER.NEXTVAL), 5, '0'), DATE '2026-09-03',
       (SELECT PARTNER_ID FROM BIZ_PARTNER WHERE PARTNER_CODE = '00002'), '未来流通',
       (SELECT WAREHOUSE_ID FROM WAREHOUSE WHERE WAREHOUSE_CODE = '00001'), '本社倉庫',
       (SELECT ASSIGNEE_ID FROM ASSIGNEE WHERE ASSIGNEE_CODE = '00002'), '鈴木花子',
       DATE '2026-09-10', '見積00002の第1回受注', 'IN_PROGRESS'
FROM DUAL;

