-- ====================================================================
-- 10. SALE_LINE (売上 明細 309件)
-- ====================================================================

-- [売上 00001 大和電子 / 本社倉庫]
-- キーボード 6 x 50,000 | 元受注 00002 キーボード 明細 | 出荷指示 6
INSERT INTO SALE_LINE (
    SALE_LINE_ID, SALE_ID, ITEM_ID, ITEM_NAME, SPECIFICATION, UNIT, QUANTITY, UNIT_PRICE, SUPPLY_AMOUNT,
    VAT_AMOUNT, TOTAL_AMOUNT, SALES_ORDER_LINE_ID,
    NOTE
)
VALUES (SEQ_SALE_LINE.NEXTVAL,
        (SELECT SALE_ID FROM SALE WHERE SALE_NO = '00001'),
        (SELECT ITEM_ID FROM ITEM WHERE ITEM_CODE = '00003'), 'キーボード', 'メカニカル / テンキーレス', 'EA',
        6, 50000, 300000, 30000, 330000,
        (SELECT OL.SALES_ORDER_LINE_ID
           FROM SALES_ORDER_LINE OL
           JOIN SALES_ORDER O ON O.SALES_ORDER_ID = OL.SALES_ORDER_ID
           JOIN ITEM I ON I.ITEM_ID = OL.ITEM_ID
          WHERE O.SALES_ORDER_NO = '00002' AND I.ITEM_CODE = '00003'),
        'キーボードの第1回分割売上');

-- マウス 5 x 20,000 | 直接売上 明細 (SALES_ORDER_LINE_ID = NULL) | 受注なしで追加した明細, 出荷指示 3 (残数量 2)
INSERT INTO SALE_LINE (
    SALE_LINE_ID, SALE_ID, ITEM_ID, ITEM_NAME, SPECIFICATION, UNIT, QUANTITY, UNIT_PRICE, SUPPLY_AMOUNT,
