    DELIVERY_ADDRESS, PROGRESS_STATUS, UPDATED_AT, DELETED_YN
)
SELECT SEQ_SHIP_INST.NEXTVAL,
       LPAD(TO_CHAR(SEQ_SHIP_INST.NEXTVAL), 5, '0'),
       ADD_MONTHS(TRUNC(SYSDATE, 'MM'), -2) + MOD(19, LAST_DAY(ADD_MONTHS(TRUNC(SYSDATE, 'MM'), -2)) - ADD_MONTHS(TRUNC(SYSDATE, 'MM'), -2) + 1),
       (SELECT PARTNER_ID FROM BIZ_PARTNER WHERE PARTNER_CODE = '00020'),
       '春風流通',
       (SELECT WAREHOUSE_ID FROM WAREHOUSE WHERE WAREHOUSE_CODE = '00056'),
       '岡山組立工場',
       (SELECT ASSIGNEE_ID FROM ASSIGNEE WHERE ASSIGNEE_CODE = '00020'),
       '山崎悠人',
       '追加出荷指示 100',
       NULL,
       NULL,
       NULL,
       NULL,
       'COMPLETED',
       CAST((ADD_MONTHS(TRUNC(SYSDATE, 'MM'), -2) + MOD(19, LAST_DAY(ADD_MONTHS(TRUNC(SYSDATE, 'MM'), -2)) - ADD_MONTHS(TRUNC(SYSDATE, 'MM'), -2) + 1)) AS TIMESTAMP),
       'N'
  FROM DUAL;

