    ASSIGNEE_ID, ASSIGNEE_NAME, NOTE, DELIVERY_CONTACT, DELIVERY_POSTAL_CODE, DELIVERY_ADDRESS,
    PROGRESS_STATUS, UPDATED_AT, DELETED_YN
)
SELECT SEQ_SHIPMENT.NEXTVAL,
       LPAD(TO_CHAR(SEQ_SHIPMENT.NEXTVAL), 5, '0'),
       TRUNC(SYSDATE, 'MM') + MOD(2, GREATEST(TRUNC(SYSDATE) - TRUNC(SYSDATE, 'MM'), 1)),
       (SELECT PARTNER_ID FROM BIZ_PARTNER WHERE PARTNER_CODE = '00116'),
       '海晴流通',
       (SELECT WAREHOUSE_ID FROM WAREHOUSE WHERE WAREHOUSE_CODE = '00013'),
       '板橋物流倉庫',
       (SELECT ASSIGNEE_ID FROM ASSIGNEE WHERE ASSIGNEE_CODE = '00033'),
       '藤田七海',
       '追加出荷 33',
       '090-0000-0116',
       '8600001',
       '熊本県熊本市サンプル町19-1-1 3階',
       'CONFIRMED',
       CAST((TRUNC(SYSDATE, 'MM') + MOD(2, GREATEST(TRUNC(SYSDATE) - TRUNC(SYSDATE, 'MM'), 1))) AS TIMESTAMP),
       'N'
  FROM DUAL;

